"use client";

import * as React from "react";
import {
  PageHeader,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
  ToastProvider,
  useToast,
} from "@gunjo/ui";

import { ClaimForm, type FileMap } from "./ClaimForm";
import { ClaimProgress } from "./ClaimProgress";
import { POLICY, type ClaimDraft, type ProgressView } from "./claim-data";

const INITIAL_DRAFT: ClaimDraft = {
  kind: "hospitalization",
  from: new Date(2026, 6, 20),
  to: new Date(2026, 6, 27),
  visitDays: 0,
  eventDate: undefined,
  hospital: "",
  disease: "虫垂炎",
  hasSurgery: true,
  surgery: "虫垂切除術",
  otherInsurer: "",
  otherInsurerCount: 0,
  accountId: "acc-main",
  newAccount: { bank: "", branch: "", kind: "futsu", number: "", holder: "" },
};

const INITIAL_FILES: FileMap = { certificate: [], receipt: [], identity: [] };

function ClaimFilingScreen() {
  const { showToast } = useToast();
  const [tab, setTab] = React.useState<"file" | "status">("file");
  const [step, setStep] = React.useState(0);
  const [draft, setDraft] = React.useState<ClaimDraft>(INITIAL_DRAFT);
  const [files, setFiles] = React.useState<FileMap>(INITIAL_FILES);
  const [submitting, setSubmitting] = React.useState(false);
  const [view, setView] = React.useState<ProgressView>("normal");

  const handleSubmit = () => {
    setSubmitting(true);
    window.setTimeout(() => {
      setSubmitting(false);
      setTab("status");
      setView("loading");
      showToast({
        message: "請求を受け付けました",
        type: "success",
        description: "受付番号をメールでもお送りしました。進み具合はこの画面で見られます。",
      });
      window.setTimeout(() => setView("normal"), 1200);
    }, 1200);
  };

  return (
    <div className="mx-auto flex min-h-dvh w-full max-w-md flex-col bg-background">
      <PageHeader
        title="給付金の請求"
        subtitle={`${POLICY.productName}・証券番号 ${POLICY.policyNumber}`}
        onBack={() => undefined}
      />

      <Tabs
        value={tab}
        onValueChange={(v) => setTab(v as "file" | "status")}
        className="flex-1"
      >
        <div className="sticky top-14 z-20 border-b border-border bg-background px-4 py-2">
          <TabsList className="w-full">
            <TabsTrigger value="file" className="flex-1">
              請求する
            </TabsTrigger>
            <TabsTrigger value="status" className="flex-1">
              出したあと
            </TabsTrigger>
          </TabsList>
        </div>

        <TabsContent value="file" className="mt-0">
          <ClaimForm
            draft={draft}
            onDraftChange={setDraft}
            files={files}
            onFilesChange={setFiles}
            step={step}
            onStepChange={setStep}
            onSubmit={handleSubmit}
            submitting={submitting}
          />
        </TabsContent>

        <TabsContent value="status" className="mt-0">
          <ClaimProgress
            view={view}
            onViewChange={setView}
            onResubmit={() => {
              setFiles((prev) => ({ ...prev, certificate: [] }));
              setStep(3);
              setTab("file");
            }}
            onStartClaim={() => {
              setStep(0);
              setTab("file");
            }}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
}

export default function ClaimFilingPage() {
  return (
    <ToastProvider placement="viewport">
      <ClaimFilingScreen />
    </ToastProvider>
  );
}

/**
 * 給付金請求（入院）— 画面で使うデータ・型・給付ルール。
 * 実在の保険会社・医療機関・個人は登場しません。すべて説明用の仮データです。
 */

export type ClaimKind = "hospitalization" | "surgery" | "outpatient" | "diagnosis";

export type DocId = "certificate" | "receipt" | "identity";

export type DocState = "required" | "not-required";

export interface DocRequirement {
  id: DocId;
  /** 書類名 */
  title: string;
  /** 何のために要るのか（1〜2文） */
  why: string;
  /** 必要／不要 */
  state: DocState;
  /** 不要のときはその理由、必要のときは補足 */
  reason: string;
  /** 撮るときの具体的な注意 */
  tips: string[];
}

export interface SavedAccount {
  id: string;
  /** 口座の呼び名（金融機関名は出しません） */
  label: string;
  description: string;
  /** 下4桁だけ */
  masked: string;
}

export interface NewAccount {
  bank: string;
  branch: string;
  kind: string;
  number: string;
  holder: string;
}

export interface ClaimDraft {
  kind: ClaimKind;
  /** 入院・通院の期間 */
  from?: Date;
  to?: Date;
  /** 通院の実日数（通院は連続しないので自動計算しない） */
  visitDays: number;
  /** 手術日・診断日 */
  eventDate?: Date;
  hospital: string;
  disease: string;
  hasSurgery: boolean;
  surgery: string;
  otherInsurer: "" | "yes" | "no";
  otherInsurerCount: number;
  accountId: string;
  newAccount: NewAccount;
}

/* ------------------------------------------------------------------ */
/* 契約内容（仮）                                                       */
/* ------------------------------------------------------------------ */

export const POLICY = {
  productName: "医療保険（総合入院タイプ）",
  policyNumber: "1234-5678-90",
  /** 入院日額 */
  hospitalDaily: 10000,
  /** 通院日額 */
  outpatientDaily: 3000,
  /** 診断給付金 */
  diagnosisLumpSum: 100000,
  /** 本人確認書類が要る金額のライン */
  identityThreshold: 1000000,
} as const;

export const CLAIM_KINDS: {
  value: ClaimKind;
  title: string;
  description: string;
}[] = [
  {
    value: "hospitalization",
    title: "入院した",
    description: "1日以上ベッドで治療を受けた。手術をしていれば、あとの画面で一緒に請求できます。",
  },
  {
    value: "surgery",
    title: "手術を受けた",
    description: "入院はせず、日帰りで手術だけを受けた。",
  },
  {
    value: "outpatient",
    title: "通院した",
    description: "入院のあと、同じ病気やけがで通いつづけた。",
  },
  {
    value: "diagnosis",
    title: "診断を受けた",
    description: "所定の病気だと医師に診断された。治療の前でも請求できます。",
  },
];

export const DISEASE_OPTIONS = [
  { value: "虫垂炎", label: "虫垂炎" },
  { value: "胆石症", label: "胆石症" },
  { value: "鼠径ヘルニア", label: "鼠径ヘルニア" },
  { value: "肺炎", label: "肺炎" },
  { value: "骨折", label: "骨折" },
  { value: "尿路結石", label: "尿路結石" },
];

export const SURGERY_OPTIONS = [
  { value: "虫垂切除術", label: "虫垂切除術", multiplier: 10 },
  { value: "胆のう摘出術", label: "胆のう摘出術", multiplier: 10 },
  { value: "鼠径ヘルニア手術", label: "鼠径ヘルニア手術", multiplier: 10 },
  { value: "骨折観血的手術", label: "骨折観血的手術", multiplier: 10 },
  { value: "内視鏡的ポリープ切除術", label: "内視鏡的ポリープ切除術", multiplier: 5 },
];

export const SAVED_ACCOUNTS: SavedAccount[] = [
  {
    id: "acc-main",
    label: "登録口座 1",
    description: "毎月の保険料を引き落としている口座",
    masked: "普通 ****3210",
  },
  {
    id: "acc-sub",
    label: "登録口座 2",
    description: "前回（2026年3月）の給付金を受け取った口座",
    masked: "普通 ****8842",
  },
];

export const NEW_ACCOUNT_ID = "new-account";

export const ACCOUNT_KINDS = [
  { value: "futsu", label: "普通" },
  { value: "toza", label: "当座" },
  { value: "chochiku", label: "貯蓄" },
];

/* ------------------------------------------------------------------ */
/* 計算                                                                 */
/* ------------------------------------------------------------------ */

const DAY_MS = 24 * 60 * 60 * 1000;

/** 開始日と終了日から日数を出す（両端を含む）。 */
export function countDays(from?: Date, to?: Date): number {
  if (!from || !to) return 0;
  const a = Date.UTC(from.getFullYear(), from.getMonth(), from.getDate());
  const b = Date.UTC(to.getFullYear(), to.getMonth(), to.getDate());
  if (b < a) return 0;
  return Math.round((b - a) / DAY_MS) + 1;
}

export function formatDate(date?: Date): string {
  if (!date) return "未入力";
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
}

export function surgeryMultiplier(name: string): number {
  return SURGERY_OPTIONS.find((o) => o.value === name)?.multiplier ?? 10;
}

export interface EstimateLine {
  label: string;
  amount: number;
  note?: string;
}

export interface Estimate {
  lines: EstimateLine[];
  total: number;
  formula: string;
}

/** 受け取れる見込みの金額。あくまで見込みで、査定で変わります。 */
export function estimate(draft: ClaimDraft): Estimate {
  const lines: EstimateLine[] = [];
  const days = countDays(draft.from, draft.to);

  if (draft.kind === "hospitalization") {
    lines.push({
      label: "入院給付金",
      amount: POLICY.hospitalDaily * days,
      note: `入院日額 ${POLICY.hospitalDaily.toLocaleString("ja-JP")}円 × ${days}日`,
    });
    if (draft.hasSurgery && draft.surgery) {
      const m = surgeryMultiplier(draft.surgery);
      lines.push({
        label: "手術給付金",
        amount: POLICY.hospitalDaily * m,
        note: `${draft.surgery}（入院日額の${m}倍）`,
      });
    }
  }

  if (draft.kind === "surgery") {
    const m = draft.surgery ? surgeryMultiplier(draft.surgery) : 10;
    lines.push({
      label: "手術給付金",
      amount: POLICY.hospitalDaily * m,
      note: `${draft.surgery || "手術"}（入院日額の${m}倍）`,
    });
  }

  if (draft.kind === "outpatient") {
    lines.push({
      label: "通院給付金",
      amount: POLICY.outpatientDaily * draft.visitDays,
      note: `通院日額 ${POLICY.outpatientDaily.toLocaleString("ja-JP")}円 × ${draft.visitDays}日`,
    });
  }

  if (draft.kind === "diagnosis") {
    lines.push({
      label: "診断給付金",
      amount: POLICY.diagnosisLumpSum,
      note: "所定の診断を受けたときに1回だけお支払い",
    });
  }

  const total = lines.reduce((sum, l) => sum + l.amount, 0);
  const formula =
    draft.kind === "hospitalization"
      ? "見込額 = 入院日額 × 入院日数 ＋ 手術給付金"
      : draft.kind === "outpatient"
        ? "見込額 = 通院日額 × 通院日数"
        : "見込額 = 給付金額（定額）";

  return { lines, total, formula };
}

/* ------------------------------------------------------------------ */
/* 必要書類のルール                                                     */
/* ------------------------------------------------------------------ */

/** 診断書がなくてよい入院日数の上限 */
export const CERTIFICATE_FREE_DAYS = 4;

export function requiredDocuments(draft: ClaimDraft): DocRequirement[] {
  const days = countDays(draft.from, draft.to);
  const total = estimate(draft).total;
  const isNewAccount = draft.accountId === NEW_ACCOUNT_ID;

  /* --- 診断書 --- */
  let certificate: DocRequirement;
  if (draft.kind === "hospitalization") {
    const needed = days > CERTIFICATE_FREE_DAYS || draft.hasSurgery;
    certificate = {
      id: "certificate",
      title: "診断書",
      why: "入院した理由・期間・手術の内容を、医師に書いてもらう書類です。当社所定の用紙があります。",
      state: needed ? "required" : "not-required",
      reason: needed
        ? draft.hasSurgery && days <= CERTIFICATE_FREE_DAYS
          ? `入院は${days}日ですが、手術を受けているため診断書が必要です。`
          : `入院が${CERTIFICATE_FREE_DAYS}日を超える（${days}日）ため必要です。`
        : `入院が${days}日（${CERTIFICATE_FREE_DAYS}日以内）で手術もないため、この請求では不要です。入院した日と退院した日は、領収書の記載で確認します。`,
      tips: [
        "1ページ目から最後まで、全ページを撮ってください。",
        "右上の「作成日」と、医師の記名・押印が写るようにしてください。",
        "用紙の四隅が切れないように、真上から撮ってください。",
      ],
    };
  } else if (draft.kind === "surgery") {
    certificate = {
      id: "certificate",
      title: "診断書",
      why: "受けた手術の名前と実施日を、医師に書いてもらう書類です。",
      state: "required",
      reason: "日帰り手術は領収書だけでは術式が分からないため、必ず必要です。",
      tips: [
        "術式（手術の名前）の欄が読めるように撮ってください。",
        "手術の実施日が写るようにしてください。",
      ],
    };
  } else if (draft.kind === "diagnosis") {
    certificate = {
      id: "certificate",
      title: "診断書",
      why: "診断された病名と、診断が確定した日を証明する書類です。",
      state: "required",
      reason: "診断給付金は診断書の内容だけで判断するため、必ず必要です。",
      tips: ["病名と確定診断日が両方写るようにしてください。"],
    };
  } else {
    certificate = {
      id: "certificate",
      title: "診断書",
      why: "入院した理由・期間を医師に書いてもらう書類です。",
      state: "not-required",
      reason:
        "通院だけの請求では、診断書のかわりに領収書と診療明細書で内容を確認します。この請求では不要です。",
      tips: [],
    };
  }

  /* --- 領収書 --- */
  const receiptNeeded = draft.kind !== "diagnosis";
  const receipt: DocRequirement = {
    id: "receipt",
    title: "領収書",
    why: "窓口で支払った金額と、治療を受けた日を確認するための書類です。",
    state: receiptNeeded ? "required" : "not-required",
    reason: receiptNeeded
      ? draft.kind === "outpatient"
        ? "通院した日ごとに1枚ずつ、期間中の分をすべて撮ってください。"
        : "入院期間の分をすべて撮ってください。医療機関の領収印があるものをお願いします。"
      : "診断給付金は治療費と関係しないため、領収書は不要です。",
    tips: [
      "金額・受診日・医療機関名の3つが必ず写るようにしてください。",
      "レシート型の細長い領収書は、折らずに広げて撮ってください。",
      "コピーでもかまいません。原本を送る必要はありません。",
    ],
  };

  /* --- 本人確認書類 --- */
  const identityNeeded = isNewAccount || total >= POLICY.identityThreshold;
  const identity: DocRequirement = {
    id: "identity",
    title: "本人確認書類",
    why: "お受け取りになる方がご契約者さまご本人かを確認します。顔写真つきの公的な証明書1点で足ります。",
    state: identityNeeded ? "required" : "not-required",
    reason: identityNeeded
      ? isNewAccount
        ? "受取口座に新しい口座を指定したため必要です。登録済みの口座を選ぶと不要になります。"
        : `見込額が${POLICY.identityThreshold.toLocaleString("ja-JP")}円以上のため必要です。`
      : "登録済みの口座にお振り込みするため、この請求では不要です。",
    tips: [
      "有効期限内のものを、おもて面いっぱいに撮ってください。",
      "4隅と、氏名・生年月日・住所が読めることを確かめてください。",
    ],
  };

  return [certificate, receipt, identity];
}

/* ------------------------------------------------------------------ */
/* 進み具合                                                             */
