export const FORM_STEPS = ["内容", "入力", "口座", "書類", "確認"] as const;

export type FileMap = Record<DocId, File[]>;

interface Props {
  draft: ClaimDraft;
  onDraftChange: (draft: ClaimDraft) => void;
  files: FileMap;
  onFilesChange: (files: FileMap) => void;
  step: number;
  onStepChange: (step: number) => void;
  onSubmit: () => void;
  submitting: boolean;
}

/* ------------------------------------------------------------------ */
/* 入力チェック                                                         */
/* ------------------------------------------------------------------ */

function validate(
  step: number,
  draft: ClaimDraft,
  files: FileMap,
): FieldErrorItem[] {
  const errors: FieldErrorItem[] = [];
  const usesPeriod = draft.kind === "hospitalization" || draft.kind === "outpatient";

  if (step === 1) {
    if (usesPeriod) {
      if (!draft.from || !draft.to) {
        errors.push({
          target: "field-period",
          message:
            draft.kind === "hospitalization"
              ? "入院した期間（入院日と退院日）を選んでください"
              : "通院した期間を選んでください",
        });
      } else if (countDays(draft.from, draft.to) === 0) {
        errors.push({ target: "field-period", message: "退院日が入院日より前になっています" });
      }
    } else if (!draft.eventDate) {
      errors.push({
        target: "field-event-date",
        message: draft.kind === "surgery" ? "手術を受けた日を選んでください" : "診断を受けた日を選んでください",
      });
    }

    if (draft.kind === "outpatient" && draft.visitDays < 1) {
      errors.push({ target: "field-visit-days", message: "通院した日数を1日以上で入れてください" });
    }
    if (!draft.hospital.trim()) {
      errors.push({ target: "field-hospital", message: "病院・クリニックの名前を入れてください" });
    }
    if (!draft.disease.trim()) {
      errors.push({ target: "field-disease", message: "病名・けがの名前を選んでください" });
    }
    if (draft.kind === "surgery" && !draft.surgery) {
      errors.push({ target: "field-surgery", message: "受けた手術を選んでください" });
    }
    if (draft.kind === "hospitalization" && draft.hasSurgery && !draft.surgery) {
      errors.push({ target: "field-surgery", message: "受けた手術を選んでください" });
    }
    if (!draft.otherInsurer) {
      errors.push({
        target: "field-other-insurer",
        message: "他の保険にも請求しているかを選んでください",
      });
    }
  }

  if (step === 2 && draft.accountId === NEW_ACCOUNT_ID) {
    const a = draft.newAccount;
    if (!a.bank.trim()) errors.push({ target: "field-bank", message: "金融機関の名前を入れてください" });
    if (!a.branch.trim()) errors.push({ target: "field-branch", message: "支店の名前を入れてください" });
    if (!/^\d{7}$/.test(a.number)) {
      errors.push({ target: "field-account-number", message: "口座番号を数字7けたで入れてください" });
    }
    if (!a.holder.trim()) errors.push({ target: "field-holder", message: "口座の名義をカタカナで入れてください" });
  }

  if (step === 3) {
    for (const doc of requiredDocuments(draft)) {
      if (doc.state === "required" && files[doc.id].length === 0) {
        errors.push({ target: `upload-${doc.id}`, message: `${doc.title}の写真がまだ出ていません` });
      }
    }
  }

  return errors;
}

/* ------------------------------------------------------------------ */

export function ClaimForm({
  draft,
  onDraftChange,
  files,
  onFilesChange,
  step,
  onStepChange,
  onSubmit,
  submitting,
}: Props) {
  const [attempt, setAttempt] = React.useState(0);
  const [showErrors, setShowErrors] = React.useState(false);
  const [confirmed, setConfirmed] = React.useState(false);

  const patch = (next: Partial<ClaimDraft>) => onDraftChange({ ...draft, ...next });

  const days = countDays(draft.from, draft.to);
  const docs = requiredDocuments(draft);
  const money = estimate(draft);
  const usesPeriod = draft.kind === "hospitalization" || draft.kind === "outpatient";
  const isNewAccount = draft.accountId === NEW_ACCOUNT_ID;

  const errors = validate(step, draft, files);
  const shown = showErrors ? errors : [];
  const errorFor = (target: string) => shown.find((e) => e.target === target)?.message;

  const goNext = () => {
    if (errors.length > 0) {
      setShowErrors(true);
      setAttempt((n) => n + 1);
      return;
    }
    setShowErrors(false);
    if (step < FORM_STEPS.length - 1) onStepChange(step + 1);
    else onSubmit();
  };

  const goBack = () => {
    setShowErrors(false);
    onStepChange(Math.max(0, step - 1));
  };

  const stepperSteps = FORM_STEPS.map((label, i) => ({
    label,
    state: (i < step ? "completed" : i === step ? "current" : "upcoming") as
      | "completed"
      | "current"
      | "upcoming",
  }));

  return (
    <div className="pb-28">
      <div className="border-b border-border bg-background">
        <Stepper
          steps={stepperSteps}
          aria-label="請求の入力の進み具合"
          onStepClick={(i) => {
            if (i <= step) {
              setShowErrors(false);
              onStepChange(i);
            }
          }}
        />
      </div>

      <Form
        className="px-4 py-5"
        onSubmit={(e) => {
          e.preventDefault();
          goNext();
        }}
      >
        {shown.length > 0 ? <ErrorSummary key={attempt} errors={shown} /> : null}

        {/* ---------- 1. 何があったか ---------- */}
        {step === 0 ? (
          <VStack gap={4}>
            <div>
              <h2 className="text-lg font-semibold">何がありましたか</h2>
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                選んだ内容によって、このあと入れる項目と、出していただく書類が変わります。
              </p>
            </div>
            <RadioCardGroup
              name="claim-kind"
              aria-label="請求する内容"
              value={draft.kind}
              onValueChange={(v) => patch({ kind: v as ClaimKind })}
              className="flex flex-col gap-2"
            >
              {CLAIM_KINDS.map((k) => (
                <RadioCard key={k.value} value={k.value} title={k.title} description={k.description} />
              ))}
            </RadioCardGroup>
            <Alert variant="info" icon={<IconInfoCircle />}>
              <AlertTitle>入院と手術は、まとめて1回で請求できます</AlertTitle>
              <AlertDescription>
                「入院した」を選ぶと、次の画面で手術のことも一緒に入れられます。分けて出す必要はありません。
              </AlertDescription>
            </Alert>
          </VStack>
        ) : null}

        {/* ---------- 2. 請求の入力 ---------- */}
        {step === 1 ? (
          <VStack gap={5}>
            <div>
              <h2 className="text-lg font-semibold">
                {draft.kind === "hospitalization"
                  ? "入院のことを教えてください"
                  : draft.kind === "surgery"
                    ? "手術のことを教えてください"
                    : draft.kind === "outpatient"
                      ? "通院のことを教えてください"
                      : "診断のことを教えてください"}
              </h2>
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                手もとの領収書を見ながら入れると早いです。
              </p>
            </div>

            {usesPeriod ? (
              <VStack gap={2}>
                <DateRangePicker
                  id="field-period"
                  label={draft.kind === "hospitalization" ? "入院した期間" : "通院した期間"}
                  description={
                    draft.kind === "hospitalization"
                      ? "入院した日と、退院した日を選んでください。"
                      : "はじめて通った日と、最後に通った日を選んでください。"
                  }
                  value={{ from: draft.from, to: draft.to }}
                  onValueChange={(r) => patch({ from: r?.from, to: r?.to })}
                  dateFormat="yyyy/MM/dd"
                  placeholder="日付を選ぶ"
                  numberOfMonths={1}
                  editable
                />
                <FieldError id="err-period" error={errorFor("field-period")} />
                {draft.kind === "hospitalization" ? (
                  <ComputedReadout
                    label="入院日数（自動で計算しています）"
                    value={days}
                    unit="日"
                    note="入院した日と退院した日の両方を数えます。日帰りの場合は1日です。"
                  />
                ) : null}
              </VStack>
            ) : (
              <VStack gap={2}>
                <DatePicker
                  id="field-event-date"
                  label={draft.kind === "surgery" ? "手術を受けた日" : "診断を受けた日"}
                  description="領収書または診断書に書いてある日付です。"
                  value={draft.eventDate}
                  onValueChange={(d) => patch({ eventDate: d })}
                  dateFormat="yyyy/MM/dd"
                  placeholder="日付を選ぶ"
                  editable
                />
                <FieldError id="err-event-date" error={errorFor("field-event-date")} />
              </VStack>
            )}

            {draft.kind === "outpatient" ? (
              <Field
                id="field-visit-days"
                label="実際に通った日数"
                description="期間のうち、実際に受診した日を数えて入れてください。"
                required
                error={errorFor("field-visit-days")}
              >
                <NumberInput
                  layout="stepper"
                  min={0}
                  max={120}
                  value={draft.visitDays}
                  onValueChange={(v) => patch({ visitDays: v })}
                />
              </Field>
            ) : null}

            <Field
              id="field-hospital"
              label="病院・クリニックの名前"
              description="領収書に書いてあるとおりに入れてください。略さなくてかまいません。"
              required
              error={errorFor("field-hospital")}
            >
              <Input
                value={draft.hospital}
                onChange={(e) => patch({ hospital: e.target.value })}
                placeholder="例）〇〇市立総合医療センター"
                autoComplete="off"
              />
            </Field>

            <Field
              id="field-disease"
              label="病名・けがの名前"
              description="一覧にないときは、入力欄に打ち込むとそのまま登録できます。"
              required
              error={errorFor("field-disease")}
            >
              <Combobox
                options={DISEASE_OPTIONS}
                value={draft.disease}
                onValueChange={(v) => patch({ disease: v })}
                onCreate={(v) => patch({ disease: v })}
                creatable
                createLabel={(v) => `「${v}」で登録する`}
                placeholder="選ぶ、または入力する"
                searchPlaceholder="病名を探す"
                emptyMessage="見つかりません。そのまま入力できます。"
              />
            </Field>

            {draft.kind === "hospitalization" ? (
              <VStack gap={3}>
                <Switch
                  checked={draft.hasSurgery}
                  onCheckedChange={(c) => patch({ hasSurgery: c, surgery: c ? draft.surgery : "" })}
                  label="この入院で手術を受けた"
                  description="手術を受けていると、入院給付金に加えて手術給付金が出ます。"
                />
                <RevealSection open={draft.hasSurgery} label="手術の内容">
                  <Field
                    id="field-surgery"
                    label="受けた手術"
                    description="診断書の「術式」の欄に書いてある名前です。"
                    required
                    error={errorFor("field-surgery")}
                  >
                    <Combobox
                      options={SURGERY_OPTIONS.map((o) => ({ value: o.value, label: o.label }))}
                      value={draft.surgery}
                      onValueChange={(v) => patch({ surgery: v })}
                      onCreate={(v) => patch({ surgery: v })}
                      creatable
                      createLabel={(v) => `「${v}」で登録する`}
                      placeholder="選ぶ、または入力する"
                      searchPlaceholder="術式を探す"
                      emptyMessage="見つかりません。そのまま入力できます。"
                    />
                  </Field>
                </RevealSection>
              </VStack>
            ) : null}

            {draft.kind === "surgery" ? (
              <Field
                id="field-surgery"
                label="受けた手術"
                description="診断書の「術式」の欄に書いてある名前です。"
                required
                error={errorFor("field-surgery")}
              >
                <Combobox
                  options={SURGERY_OPTIONS.map((o) => ({ value: o.value, label: o.label }))}
                  value={draft.surgery}
                  onValueChange={(v) => patch({ surgery: v })}
                  onCreate={(v) => patch({ surgery: v })}
                  creatable
                  createLabel={(v) => `「${v}」で登録する`}
                  placeholder="選ぶ、または入力する"
                  searchPlaceholder="術式を探す"
                  emptyMessage="見つかりません。そのまま入力できます。"
                />
              </Field>
            ) : null}

            <Separator />

            <VStack gap={2}>
              <p id="other-insurer-label" className="text-sm font-medium leading-none">
                他の保険会社にも、同じ入院・けがで請求していますか
                <span aria-hidden="true" className="ml-0.5 text-destructive">
                  *
                </span>
              </p>
              <p id="other-insurer-desc" className="text-xs text-muted-foreground">
                重ねて請求しても減額はされません。事実どおりに選んでください。
              </p>
              <RadioGroup
                aria-labelledby="other-insurer-label"
                aria-describedby="other-insurer-desc"
                value={draft.otherInsurer}
                onValueChange={(v) => patch({ otherInsurer: v as "yes" | "no" })}
                className="mt-1 flex flex-col gap-2"
              >
                <RadioGroupItem id="field-other-insurer" value="yes" label="はい、他の保険にも請求している" />
                <RadioGroupItem value="no" label="いいえ、この保険だけに請求する" />
              </RadioGroup>
              <FieldError id="err-other-insurer" error={errorFor("field-other-insurer")} />
              <RevealSection open={draft.otherInsurer === "yes"} label="他の保険への請求">
                <VStack gap={3} className="pt-1">
                  <Field
                    id="field-other-count"
                    label="他の保険に出した件数"
                    description="会社名は入りません。件数だけで足ります。"
                  >
                    <NumberInput
                      layout="stepper"
                      min={0}
                      max={10}
                      value={draft.otherInsurerCount}
                      onValueChange={(v) => patch({ otherInsurerCount: v })}
                    />
                  </Field>
                  <Alert variant="info" icon={<IconInfoCircle />}>
                    <AlertDescription>
                      領収書の原本を他社に出していてもかまいません。当社にはコピーの写真を出してください。
                    </AlertDescription>
                  </Alert>
                </VStack>
              </RevealSection>
            </VStack>
          </VStack>
        ) : null}

        {/* ---------- 3. 受取口座 ---------- */}
        {step === 2 ? (
          <VStack gap={4}>
            <div>
              <h2 className="text-lg font-semibold">どこにお振り込みしますか</h2>
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                登録済みの口座を選ぶと、本人確認書類を出さずにすみます。
              </p>
            </div>
            <RadioCardGroup
              name="payout-account"
              aria-label="受取口座"
              value={draft.accountId}
              onValueChange={(v) => patch({ accountId: v })}
              className="flex flex-col gap-2"
            >
              {SAVED_ACCOUNTS.map((a) => (
                <RadioCard
                  key={a.id}
                  value={a.id}
                  title={a.label}
                  description={a.description}
                  price={<span className="text-sm font-medium tabular-nums">{a.masked}</span>}
                  highlight="本人確認書類はいりません"
                />
              ))}
              <RadioCard
                value={NEW_ACCOUNT_ID}
                title="別の口座を指定する"
                description="ここで新しく口座を入れます。あわせて本人確認書類の提出が必要になります。"
              />
            </RadioCardGroup>

            <RevealSection open={isNewAccount} label="新しい口座の情報">
              <VStack gap={4} className="pt-1">
                <Field id="field-bank" label="金融機関の名前" required error={errorFor("field-bank")}>
                  <Input
                    value={draft.newAccount.bank}
                    onChange={(e) => patch({ newAccount: { ...draft.newAccount, bank: e.target.value } })}
                    placeholder="例）〇〇信用金庫"
                    autoComplete="off"
                  />
                </Field>
                <Field id="field-branch" label="支店の名前" required error={errorFor("field-branch")}>
                  <Input
                    value={draft.newAccount.branch}
                    onChange={(e) => patch({ newAccount: { ...draft.newAccount, branch: e.target.value } })}
                    placeholder="例）本店営業部"
                    autoComplete="off"
                  />
                </Field>
                <Field id="field-account-kind" label="預金の種類">
                  <Select
                    value={draft.newAccount.kind}
                    onChange={(e) => patch({ newAccount: { ...draft.newAccount, kind: e.target.value } })}
                  >
                    {ACCOUNT_KINDS.map((k) => (
                      <option key={k.value} value={k.value}>
                        {k.label}
                      </option>
                    ))}
                  </Select>
                </Field>
                <Field
                  id="field-account-number"
                  label="口座番号"
                  description="数字7けた。7けたに満たないときは、先頭に0を足してください。"
                  required
                  error={errorFor("field-account-number")}
                >
                  <Input
                    value={draft.newAccount.number}
                    onChange={(e) =>
                      patch({
                        newAccount: {
                          ...draft.newAccount,
                          number: e.target.value.replace(/\D/g, "").slice(0, 7),
                        },
                      })
                    }
                    inputMode="numeric"
                    placeholder="0000000"
                    autoComplete="off"
                  />
                </Field>
                <Field
                  id="field-holder"
                  label="口座の名義"
                  description="通帳やキャッシュカードのとおり、カタカナで入れてください。"
                  required
                  error={errorFor("field-holder")}
                >
                  <Input
                    value={draft.newAccount.holder}
                    onChange={(e) => patch({ newAccount: { ...draft.newAccount, holder: e.target.value } })}
                    placeholder="ホケン タロウ"
                    autoComplete="off"
                  />
                </Field>
              </VStack>
            </RevealSection>
          </VStack>
        ) : null}

        {/* ---------- 4. 必要書類 ---------- */}
        {step === 3 ? (
          <VStack gap={4}>
            <div>
              <h2 className="text-lg font-semibold">書類を写真で出してください</h2>
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                ここまでの入力から、この請求で要るものだけを出しています。要らないものには「この請求では不要」と付いています。
              </p>
            </div>
            <Alert variant="default" icon={<IconInfoCircle />}>
              <AlertTitle>
                出していただくのは{docs.filter((d) => d.state === "required").length}点です
              </AlertTitle>
              <AlertDescription>
                原本を郵送する必要はありません。写真がはっきり読めれば、それで受け付けます。
              </AlertDescription>
            </Alert>
            {docs.map((doc) => (
              <DocumentRequirementCard
                key={doc.id}
                doc={doc}
                files={files[doc.id]}
                onFilesChange={(next) => onFilesChange({ ...files, [doc.id]: next })}
              />
            ))}
          </VStack>
        ) : null}

        {/* ---------- 5. 確認 ---------- */}
        {step === 4 ? (
          <VStack gap={4}>
            <div>
              <h2 className="text-lg font-semibold">この内容で出します</h2>
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                まちがいがないか、最後に見てください。
              </p>
            </div>

            <Card>
              <CardHeader className="pb-2">
                <div className="flex items-start justify-between gap-2">
                  <CardTitle as="h3" className="text-base">
                    入力した内容
                  </CardTitle>
                  <Button type="button" variant="outline" size="sm" onClick={() => onStepChange(1)}>
                    直す
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <MetadataList
                  wrap
                  items={[
                    {
                      label: "請求する内容",
                      value: CLAIM_KINDS.find((k) => k.value === draft.kind)?.title ?? "",
                    },
                    ...(usesPeriod
                      ? [
                          {
                            label: draft.kind === "hospitalization" ? "入院した期間" : "通院した期間",
                            value: `${formatDate(draft.from)} 〜 ${formatDate(draft.to)}`,
                          },
                          {
                            label: draft.kind === "hospitalization" ? "入院日数" : "通った日数",
                            value:
                              draft.kind === "hospitalization" ? `${days}日` : `${draft.visitDays}日`,
                          },
                        ]
                      : [
                          {
                            label: draft.kind === "surgery" ? "手術を受けた日" : "診断を受けた日",
                            value: formatDate(draft.eventDate),
                          },
                        ]),
                    { label: "病院・クリニック", value: draft.hospital || "未入力" },
                    { label: "病名・けが", value: draft.disease || "未入力" },
                    {
                      label: "手術",
                      value:
                        draft.kind === "surgery" || draft.hasSurgery
                          ? draft.surgery || "未入力"
                          : "なし",
                    },
                    {
                      label: "他の保険への請求",
                      value:
                        draft.otherInsurer === "yes"
                          ? `あり（${draft.otherInsurerCount}件）`
                          : "なし",
                    },
                    {
                      label: "受取口座",
                      value: isNewAccount
                        ? `新しい口座（${draft.newAccount.bank || "未入力"}）`
                        : (SAVED_ACCOUNTS.find((a) => a.id === draft.accountId)?.masked ?? "未選択"),
                    },
                  ]}
                />
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle as="h3" className="text-base">
                  受け取れる見込みの金額
                </CardTitle>
              </CardHeader>
              <CardContent>
                <VStack gap={3}>
                  <AmountBreakdown
                    lines={money.lines.map((l) => ({
                      label: l.label,
                      amount: l.amount,
                      note: l.note,
                    }))}
                    total={{ label: "受け取れる見込みの金額", amount: money.total }}
                    formula={money.formula}
                  />
                  <Alert variant="warning" icon={<IconAlertTriangle />}>
                    <AlertTitle>これは見込みの金額です</AlertTitle>
                    <AlertDescription>
                      実際にお支払いする金額は、診断書の内容を見て決めます（査定）。増えることも減ることもあります。ご契約の内容によっては、お支払いできない場合もあります。
                    </AlertDescription>
                  </Alert>
                </VStack>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <div className="flex items-start justify-between gap-2">
                  <CardTitle as="h3" className="text-base">
                    出す書類
                  </CardTitle>
                  <Button type="button" variant="outline" size="sm" onClick={() => onStepChange(3)}>
                    直す
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <CheckList
                  items={docs.map((doc) => ({
                    id: doc.id,
                    label: doc.title,
                    description:
                      doc.state === "not-required" ? doc.reason : `${files[doc.id].length}枚を出します`,
                    trailing:
                      doc.state === "not-required" ? (
                        <Badge variant="outline">不要</Badge>
                      ) : files[doc.id].length > 0 ? (
                        <Badge variant="success">提出済</Badge>
                      ) : (
                        <Badge variant="warning">未提出</Badge>
                      ),
                  }))}
                />
              </CardContent>
            </Card>

            <Checkbox
              checked={confirmed}
              onCheckedChange={setConfirmed}
              label="入力した内容にまちがいがないことを確認しました"
              description="事実と違う内容で請求すると、給付金をお支払いできないことがあります。"
            />
          </VStack>
        ) : null}
      </Form>

      <BottomActionBar
        stack={step === 4}
        actions={
          <div className="flex w-full items-center gap-2">
            {step > 0 ? (
              <Button type="button" variant="outline" size="touch" onClick={goBack} className="shrink-0">
                <Icon icon={IconArrowLeft} size="sm" decorative />
                戻る
              </Button>
            ) : null}
            <Button
              type="button"
              variant="primary"
              size="touch"
              className="flex-1"
              onClick={goNext}
              loading={submitting}
              disabled={step === 4 && !confirmed}
            >
              {step === 4 ? (
                <>
                  <Icon icon={IconSend} size="sm" decorative />
                  この内容で請求する
                </>
              ) : (
                "次へ"
              )}
            </Button>
          </div>
        }
      >
        <div className="min-w-0">
          <div className="text-xs text-muted-foreground">見込額（査定で変わります）</div>
          <div className="truncate text-base font-semibold tabular-nums">
            {formatCurrency(money.total)}
          </div>
        </div>
      </BottomActionBar>

      <p className="sr-only" aria-live="polite">
        {`${FORM_STEPS.length}段階のうち${step + 1}段階目：${FORM_STEPS[step]}`}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  IconAlertTriangle,
  IconCamera,
  IconCheck,
  IconClockHour4,
  IconFileText,
  IconX,
} from "@tabler/icons-react";
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Button,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  EmptyState,
  formatCurrency,
  HStack,
  Icon,
  List,
  ListCard,
  ListItem,
  MetadataList,
  RouteStops,
  SectionList,
  SegmentedControl,
  Separator,
  Skeleton,
  VStack,
  type RouteStopItem,
} from "@gunjo/ui";

import {
  PAST_CLAIMS,
  progressSteps,
  RETURN_REASONS,
  type ProgressView,
} from "./claim-data";

interface Props {
  view: ProgressView;
  onViewChange: (view: ProgressView) => void;
  /** 差し戻しの「出し直す」から、入力の書類ステップへ飛ばす */
  onResubmit: () => void;
  /** 空状態から新しい請求へ */
  onStartClaim: () => void;
}

const RESULT_BADGE: Record<
  "paid" | "partial" | "declined",
  { variant: "success" | "warning" | "secondary"; icon: React.ReactNode }
> = {
  paid: { variant: "success", icon: <IconCheck /> },
  partial: { variant: "warning", icon: <IconAlertTriangle /> },
  declined: { variant: "secondary", icon: <IconX /> },
};

export function ClaimProgress({ view, onViewChange, onResubmit, onStartClaim }: Props) {
  const returned = view === "returned";
  const steps = progressSteps(view);

  const firstPending = steps.findIndex((s) => !s.doneAt);
  const stops: RouteStopItem[] = steps.map((s, i) => {
    const status: RouteStopItem["status"] = s.doneAt
      ? "completed"
      : returned && s.id === "documents"
        ? "failed"
        : !returned && i === firstPending
          ? "current"
          : "pending";
    return {
      id: s.id,
      seq: i + 1,
      title: s.title,
      description: s.description,
      status,
      // 済んだところには日時を、これからのところには目安を出す
      dateLabel: s.doneAt ? `${s.doneAt} 完了` : undefined,
      meta: s.doneAt ? undefined : s.guide,
    };
  });

  const years = Array.from(new Set(PAST_CLAIMS.map((c) => c.year)));

  return (
    <div className="px-4 py-5">
      <VStack gap={5}>
        {/* 表示の切り替え（この画面を見せるためのもの） */}
        <div className="rounded-md border border-dashed border-border p-3">
          <p className="mb-2 text-xs text-muted-foreground">
            表示の確認用：状態を切り替えられます
          </p>
          <SegmentedControl
            aria-label="表示する状態"
            size="lg"
            options={[
              { value: "normal", label: "審査中" },
              { value: "returned", label: "差し戻し" },
              { value: "loading", label: "読み込み中" },
              { value: "empty", label: "請求なし" },
            ]}
            value={view}
            onValueChange={(v) => onViewChange(v as ProgressView)}
          />
        </div>

        {/* ---------- 読み込み中 ---------- */}
        {view === "loading" ? (
          <VStack gap={4} aria-busy="true" aria-live="polite">
            <span className="sr-only">請求の状況を読み込んでいます</span>
            <Card>
              <CardHeader className="pb-2">
                <Skeleton shape="text" className="h-5 w-40" />
              </CardHeader>
              <CardContent>
                <VStack gap={2}>
                  <Skeleton shape="text" className="h-4 w-2/3" />
                  <Skeleton shape="text" className="h-4 w-1/2" />
                </VStack>
              </CardContent>
            </Card>
            <VStack gap={3}>
              {[0, 1, 2, 3].map((i) => (
                <HStack key={i} gap={3} align="start">
                  <Skeleton shape="circle" className="h-8 w-8 shrink-0" />
                  <VStack gap={2} className="flex-1">
                    <Skeleton shape="text" className="h-4 w-24" />
                    <Skeleton shape="text" className="h-3 w-full" />
                  </VStack>
                </HStack>
              ))}
            </VStack>
          </VStack>
        ) : null}

        {/* ---------- 請求がまだ無い ---------- */}
        {view === "empty" ? (
          <EmptyState
            icon={<Icon icon={IconFileText} size="xl" decorative />}
            title="まだ請求はありません"
            description="入院・手術・通院・診断のいずれかがあったときは、ここから請求できます。だいたい5分で出せます。"
            action={
              <Button size="touch" variant="primary" onClick={onStartClaim}>
                請求をはじめる
              </Button>
            }
          />
        ) : null}

        {/* ---------- 審査中／差し戻し ---------- */}
        {view === "normal" || view === "returned" ? (
          <>
            <Card>
              <CardHeader className="pb-2">
                <HStack justify="between" align="start" gap={2}>
                  <VStack gap={0}>
                    <CardTitle as="h2" className="text-base">
                      入院給付金の請求
                    </CardTitle>
                    <p className="text-sm text-muted-foreground">虫垂炎・入院8日</p>
                  </VStack>
                  {returned ? (
                    <Badge variant="destructive" icon={<IconAlertTriangle />}>
                      対応が必要
                    </Badge>
                  ) : (
                    <Badge variant="info" icon={<IconClockHour4 />}>
                      査定中
                    </Badge>
                  )}
                </HStack>
              </CardHeader>
              <CardContent>
                <MetadataList
                  layout="horizontal"
                  variant="compact"
                  items={[
                    { label: "受付番号", value: "R-2026-080314" },
                    { label: "請求した日", value: "2026年8月3日" },
                    { label: "見込額", value: formatCurrency(180000) },
                  ]}
                />
              </CardContent>
            </Card>

            {returned ? (
              <Alert variant="destructive" icon={<IconAlertTriangle />}>
                <AlertTitle as="h2">診断書の日付が読み取れません</AlertTitle>
                <AlertDescription>
                  <p className="leading-relaxed">
                    2026年8月5日に確認したところ、次の点で判断できませんでした。この3点を直して、もう一度出してください。ほかの書類はそのままで大丈夫です。
                  </p>
                  <List variant="ordered" marker="number" spacing="tight" className="mt-3">
                    {RETURN_REASONS.map((r) => (
                      <ListItem key={r} className="text-sm leading-relaxed">
                        {r}
                      </ListItem>
                    ))}
                  </List>
                  <p className="mt-3 text-xs">
                    出し直していただいてから、査定まで3営業日ほどかかります。
                  </p>
                  <div className="mt-3">
                    <Button size="touch" variant="primary" onClick={onResubmit} className="w-full">
                      <Icon icon={IconCamera} size="sm" decorative />
                      診断書を撮り直して出す
                    </Button>
                  </div>
                </AlertDescription>
              </Alert>
            ) : null}

            <section aria-labelledby="progress-heading">
              <h2 id="progress-heading" className="mb-1 text-base font-semibold">
                いまどこまで進んでいるか
              </h2>
              <p className="mb-3 text-sm leading-relaxed text-muted-foreground">
                済んだところには日時が、これからのところには目安の日数が出ています。
              </p>
              <RouteStops
                stops={stops}
                aria-label="請求の進み具合"
                statusLabels={{
                  pending: "これから",
                  current: "進行中",
                  completed: "完了",
                  failed: "要対応",
                  delayed: "遅れ",
                }}
                currentLabel="いまここ"
              />
              <p className="mt-3 text-xs leading-relaxed text-muted-foreground">
                目安の日数は、書類がそろっていて追加の確認がいらない場合のものです。医療機関への照会が必要なときは、これより時間がかかります。
              </p>
            </section>

            <Separator />

            <section aria-labelledby="history-heading">
              <h2 id="history-heading" className="mb-3 text-base font-semibold">
                これまでの請求
              </h2>
              <SectionList
                label="これまでの請求の一覧"
                sections={years.map((year) => {
                  const rows = PAST_CLAIMS.filter((c) => c.year === year);
                  return {
                    key: year,
                    title: year,
                    meta: `${rows.length}件`,
                    content: (
                      <VStack gap={2} className="py-2">
                        {rows.map((c) => (
                          <ListCard
                            key={c.id}
                            title={c.title}
                            description={
                              <>
                                <span className="block">{c.description}</span>
                                <span className="block text-xs">{c.filedOn}</span>
                              </>
                            }
                            status={
                              <Badge
                                variant={RESULT_BADGE[c.result].variant}
                                icon={RESULT_BADGE[c.result].icon}
                              >
                                {c.resultLabel}
                              </Badge>
                            }
                            meta={
                              <span className="tabular-nums">
                                {c.amount > 0 ? formatCurrency(c.amount) : "支払なし"}
                              </span>
                            }
                          />
                        ))}
                      </VStack>
                    ),
                  };
                })}
              />
            </section>
          </>
        ) : null}
      </VStack>
    </div>
  );
}

