  Icon,
  ImagePreview,
  List,
  ListItem,
  VStack,
} from "@gunjo/ui";

import type { DocRequirement } from "./claim-data";

/* ------------------------------------------------------------------ */
/* 1. 自動計算された値の読み上げ枠                                        */
/*    （入力の結果として出てくる読み取り専用の値。Statistic はカード型の    */
/*     KPI、MetadataList は dl なので、フォームの途中に置く用途に合わず）   */
/* ------------------------------------------------------------------ */

export function ComputedReadout({
  label,
  value,
  unit,
  note,
}: {
  label: string;
  value: React.ReactNode;
  unit?: string;
  note?: React.ReactNode;
}) {
  return (
    <div
      role="status"
      aria-live="polite"
      className="rounded-md border border-dashed border-border bg-muted/40 px-3 py-2.5"
    >
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="mt-0.5 flex items-baseline gap-1">
        <span className="text-2xl font-semibold tabular-nums text-foreground">{value}</span>
        {unit ? <span className="text-sm text-muted-foreground">{unit}</span> : null}
      </div>
      {note ? <p className="mt-1 text-xs leading-relaxed text-muted-foreground">{note}</p> : null}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* 2. 入力エラーのまとめ                                                 */
/*    （エラー件数を読み上げ、押すと該当の入力へ飛ぶ。フォーム全体の       */
/*     エラーサマリに当たる部品が見つからなかったため自前）                */
/* ------------------------------------------------------------------ */

export interface FieldError {
  /** 飛び先の入力の id */
  target: string;
  message: string;
}

export function ErrorSummary({ errors }: { errors: FieldError[] }) {
  const ref = React.useRef<HTMLDivElement>(null);

  // 親から key を変えて差し替える前提。出るたびに1回だけ焦点を移す。
  React.useEffect(() => {
    ref.current?.focus();
  }, []);

  if (errors.length === 0) return null;

  return (
    <div
      ref={ref}
      role="alert"
      tabIndex={-1}
      className="rounded-md border border-destructive/40 bg-destructive/10 p-3 outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      <p className="text-sm font-semibold text-destructive">
        入力を{errors.length}か所、直してください
      </p>
      <List variant="unordered" marker="dot" spacing="tight" className="mt-2">
        {errors.map((e) => (
          <ListItem key={e.target} className="text-sm">
            <button
              type="button"
              className="text-left underline underline-offset-2 hover:no-underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              onClick={() => {
                const el = document.getElementById(e.target);
                el?.scrollIntoView({ block: "center" });
                el?.focus();
              }}
            >
              {e.message}
            </button>
          </ListItem>
        ))}
      </List>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* 3. 写真で出す欄                                                       */
/*    （FileUploader にカメラ起動も画像サムネイルも無いため、             */
/*     撮影ボタンとサムネイル一覧を足した）                               */
/* ------------------------------------------------------------------ */

const ACCEPTED = {
  "image/*": [".jpg", ".jpeg", ".png", ".heic"],
  "application/pdf": [".pdf"],
};

export function PhotoField({
  id,
  labelledBy,
  files,
  onFilesChange,
}: {
  id: string;
  labelledBy: string;
  files: File[];
  onFilesChange: (files: File[]) => void;
}) {
  const captureRef = React.useRef<HTMLInputElement>(null);

  // サムネイル用の URL を作って、使い終わったら破棄する
  const urls = React.useMemo(() => {
    const next: Record<string, string> = {};
    files.forEach((f, i) => {
      if (f.type.startsWith("image/")) next[`${i}-${f.name}`] = URL.createObjectURL(f);
    });
    return next;
  }, [files]);

  React.useEffect(
    () => () => {
      Object.values(urls).forEach((u) => URL.revokeObjectURL(u));
    },
    [urls],
  );

  return (
    <VStack gap={3}>
      <input
        ref={captureRef}
        type="file"
        accept="image/*"
        capture="environment"
        multiple
        className="sr-only"
        tabIndex={-1}
        aria-hidden="true"
        onChange={(e) => {
          const picked = Array.from(e.target.files ?? []);
          if (picked.length > 0) onFilesChange([...files, ...picked]);
          e.target.value = "";
        }}
      />
      <Button
        type="button"
        size="touch"
        className="w-full"
        onClick={() => captureRef.current?.click()}
      >
        <Icon icon={IconCamera} size="sm" decorative />
        カメラで撮る
      </Button>

      <div role="group" aria-labelledby={labelledBy}>
        <FileUploader
          id={id}
          value={files}
          onValueChange={onFilesChange}
          accept={ACCEPTED}
          maxFiles={8}
          maxSize={10 * 1024 * 1024}
          showFileList={false}
          className="w-full max-w-none"
          labels={{
            browse: "スマホの写真から選ぶ",
            drop: "ここに写真をドロップ",
            maxSize: (mb) => `1枚あたり ${mb}MB まで・8枚まで`,
            fileTooLarge: "写真が大きすぎます。撮り直すか、小さいものを選んでください。",
            fileTypeNotAccepted: "写真（JPG・PNG・HEIC）か PDF を選んでください。",
          }}
        />
      </div>

      {files.length > 0 ? (
        <div>
          <p className="mb-2 text-xs text-muted-foreground">
            提出する写真 {files.length}枚（押すと大きく見られます）
          </p>
          <ul className="grid grid-cols-3 gap-2">
            {files.map((f, i) => {
              const key = `${i}-${f.name}`;
              return (
                <li key={key} className="min-w-0">
                  <ImagePreview
                    src={urls[key]}
                    alt={`${f.name}（${i + 1}枚目）`}
                    aspectRatio="square"
                    objectFit="cover"
                    noImageLabel="PDF"
                    previewLabel="大きく見る"
                    className="rounded-md border border-border"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="touch"
                    className="mt-1 w-full text-xs"
                    aria-label={`${i + 1}枚目の写真を消す`}
                    onClick={() => onFilesChange(files.filter((_, j) => j !== i))}
                  >
                    <Icon icon={IconTrash} size="xs" decorative />
                    消す
                  </Button>
                </li>
              );
            })}
          </ul>
        </div>
      ) : null}
    </VStack>
  );
}

/* ------------------------------------------------------------------ */
/* 4. 必要書類のカード                                                   */
/*    （書類名・なぜ要るか・この請求で必要か不要か・撮り方・提出状態を     */
/*     ひとまとめにしたもの。DocumentRow はダウンロード用の行なので別物）  */
/* ------------------------------------------------------------------ */

export function DocumentRequirementCard({
  doc,
  files,
  onFilesChange,
}: {
  doc: DocRequirement;
  files: File[];
  onFilesChange: (files: File[]) => void;
}) {
  const notRequired = doc.state === "not-required";
  const submitted = files.length > 0;
  const titleId = `doc-title-${doc.id}`;

  return (
    <Card className={notRequired ? "opacity-80" : undefined}>
      <CardHeader className="pb-3">
        <HStack justify="between" align="start" gap={2}>
          <CardTitle as="h3" id={titleId} className="text-base">
            {doc.title}
          </CardTitle>
          {notRequired ? (
            <Badge variant="outline" icon={<IconMinus />}>
              この請求では不要
            </Badge>
          ) : submitted ? (
            <Badge variant="success" icon={<IconCheck />}>
              {files.length}枚を提出
            </Badge>
          ) : (
            <Badge variant="warning">必要・未提出</Badge>
          )}
        </HStack>
      </CardHeader>

      <CardContent>
        <VStack gap={3}>
          <p className="text-sm leading-relaxed text-muted-foreground">{doc.why}</p>

          <div
            className={
              notRequired
                ? "rounded-md bg-muted px-3 py-2 text-sm leading-relaxed text-muted-foreground"
                : "rounded-md bg-muted px-3 py-2 text-sm leading-relaxed text-foreground"
            }
          >
            {notRequired ? "不要な理由：" : "必要な理由："}
            {doc.reason}
          </div>

          {notRequired ? null : (
            <>
              {doc.tips.length > 0 ? (
                <div>
                  <p className="mb-1.5 text-sm font-medium">撮るときの注意</p>
                  <List variant="unordered" marker="dot" spacing="tight">
                    {doc.tips.map((t) => (
                      <ListItem key={t} className="text-sm leading-relaxed text-muted-foreground">
                        {t}
                      </ListItem>
                    ))}
                  </List>
                </div>
              ) : null}

              <PhotoField
                id={`upload-${doc.id}`}
                labelledBy={titleId}
                files={files}
                onFilesChange={onFilesChange}
              />
            </>
          )}
        </VStack>
      </CardContent>
    </Card>
  );
}

/* ------------------------------------------------------------------ */
/* 5. 1項目ぶんのフォーム欄                                              */
/*    （FormField は wiring を配る側だが p-4 が焼き込まれていて、p-0 と    */
/*     幅そろえを持つ FormGroup には context が無い。両方が要るので、     */
/*     公開されている formGroupVariants() を FormField に重ねている）      */
/* ------------------------------------------------------------------ */

export function Field({
  id,
  label,
  description,
  error,
  required,
  children,
}: {
  id?: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  children: React.ReactElement;
}) {
  return (
    <FormField id={id} error={error} required={required} className={formGroupVariants()}>
      <FormLabel>{label}</FormLabel>
      <FormControl>{children}</FormControl>
      {description ? <FormDescription>{description}</FormDescription> : null}
      <FormMessage />
    </FormField>
  );
}

/**
 * DatePicker / DateRangePicker は label・description を自前で持っていて、
 * 外から aria-describedby を渡せない。エラーだけ横に出す。
 */
export function FieldError({ id, error }: { id: string; error?: React.ReactNode }) {
  if (!error) return null;
  return (
    <p id={id} role="alert" className="text-xs font-medium text-destructive">
      {error}
    </p>
  );
}
